import {QrkAuthService} from '../data/qrk-auth-service.js';
import {resolveQrkConfig} from '../data/qrk-config.js';
import {DEVELOPMENT_CLIENTS,QRK_CLIENTS_KEY,SERVICE_PRESETS,normalizeServiceProfile,presetSettings} from '../data/qrk-service-presets.js';
const $=selector=>document.querySelector(selector),$$=selector=>[...document.querySelectorAll(selector)],CLIENTS_KEY=QRK_CLIENTS_KEY,authService=new QrkAuthService(resolveQrkConfig());
let clients=readClients(),toastTimer;
function readClients(){let saved=[];try{const value=JSON.parse(localStorage.getItem(CLIENTS_KEY)||'[]');if(Array.isArray(value))saved=value}catch{}const canonicalSlugs=new Set(DEVELOPMENT_CLIENTS.map(client=>client.slug)),merged=[...saved.filter(client=>!canonicalSlugs.has(client.slug)),...DEVELOPMENT_CLIENTS];localStorage.setItem(CLIENTS_KEY,JSON.stringify(merged));return merged}
function saveClients(){localStorage.setItem(CLIENTS_KEY,JSON.stringify(clients))}
function esc(value){return String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]))}
function segment(value){return String(value||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'')}
function usernameSegment(value){return String(value||'').toLowerCase().replace(/[^a-z0-9_-]+/g,'')}
function announce(message){const toast=$('#platform-toast');toast.textContent=message;toast.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.hidden=true,3200)}
function initializeThemeEditor(){
  const nav=$('.platform-sidebar nav'),workspace=$('.platform-content');
  nav.insertAdjacentHTML('beforeend','<button type="button" data-admin-view="appearance">Appearance</button>');
  const fields=[['accent','Accent','Buttons, links, and active states'],['page','Page background','Workspace canvas'],['surface','Surface','Cards and top bars'],['text','Text','Primary content'],['sidebar','Sidebar','Global navigation background'],['muted','Muted text','Secondary labels and descriptions'],['border','Borders','Cards, fields, and dividers'],['icon','Icon background','Small icon tiles and quiet controls'],['badge','Navigation badge','Menu count and alert badges'],['badgeText','Badge number text','Numbers shown inside badges'],['success','Success','Available, open, and completed states'],['warning','Warning','Attention and waiting states'],['danger','Danger','Errors and destructive actions']];
  const fieldMarkup=fields.map(([key,label,help])=>`<label class="theme-color-field"><input type="color" name="${key}"><span>${label}<small>${help}</small></span></label>`).join('');
  workspace.insertAdjacentHTML('beforeend',`<section data-view-panel="appearance" hidden><div class="platform-heading"><div><p class="eyebrow">GLOBAL STYLES</p><h1>Appearance.</h1><p>Choose a ready-made theme or fine-tune every shared color.</p></div></div><section class="platform-card theme-section"><div class="platform-card-heading"><div><h2>Theme</h2><p>Select the active website mode and a complete preset.</p></div><div class="theme-mode-switch" role="group" aria-label="Website color mode"><button type="button" data-theme-mode="light">Light</button><button type="button" data-theme-mode="dark">Dark</button></div></div><div class="theme-preset-groups"><div><h3>Light mode presets</h3><div class="theme-preset-grid" data-preset-grid="light"></div></div><div><h3>Dark mode presets</h3><div class="theme-preset-grid" data-preset-grid="dark"></div></div></div></section><details class="platform-card advanced-theme"><summary><span><strong>Advanced settings</strong><small>Edit all global tokens independently for light and dark mode.</small></span><span aria-hidden="true">+</span></summary><form id="theme-form"><div class="advanced-mode-tabs" role="tablist" aria-label="Advanced color mode"><button type="button" role="tab" data-edit-mode="light">Light mode colors</button><button type="button" role="tab" data-edit-mode="dark">Dark mode colors</button></div><div class="theme-color-grid">${fieldMarkup}</div><p class="theme-note">Changes preview immediately. Readable foreground colors are chosen automatically for the accent and sidebar.</p><div class="theme-actions"><button class="button outline" type="button" id="reset-theme">Reset this mode</button><button class="button primary" type="submit">Save custom colors</button></div></form></details><section class="platform-card theme-preview" aria-label="Theme preview"><div class="platform-card-heading"><div><h2>Live preview</h2><p>Representative dashboard surfaces</p></div></div><div class="theme-preview-window"><div class="theme-preview-top"></div><div class="theme-preview-body"><div class="theme-preview-nav"><b class="theme-preview-brand">QRK</b><span>Dashboard</span></div><div class="theme-preview-content"><strong>Business overview</strong><span>Today at a glance</span><div class="theme-preview-cards"><i></i><i></i><i></i><i></i></div></div></div></div></section></section>`);
  const form=$('#theme-form'),api=window.QrkGlobalTheme;
  let editMode=api.readState().mode;
  const renderPresets=()=>{const state=api.readState();for(const mode of ['light','dark']){$(`[data-preset-grid="${mode}"]`).innerHTML=Object.entries(api.presets[mode]).map(([id,preset])=>`<button class="theme-preset${state[`${mode}Preset`]===id?' selected':''}" type="button" data-use-preset="${id}" data-preset-mode="${mode}" aria-pressed="${state[`${mode}Preset`]===id}"><span class="preset-swatches">${['sidebar','accent','page','surface'].map(key=>`<i style="--preset-color:${preset.colors[key]}"></i>`).join('')}</span><strong>${preset.name}</strong><small>${preset.description}</small></button>`).join('')}};
  const fill=theme=>api.tokenKeys.forEach(key=>form.elements[key].value=theme[key]);
  const values=()=>Object.fromEntries(api.tokenKeys.map(key=>[key,form.elements[key].value]));
  const sync=()=>{const state=api.readState();$$('[data-theme-mode]').forEach(button=>{const active=button.dataset.themeMode===state.mode;button.classList.toggle('active',active);button.setAttribute('aria-pressed',active)});$$('[data-edit-mode]').forEach(button=>{const active=button.dataset.editMode===editMode;button.classList.toggle('active',active);button.setAttribute('aria-selected',active)});fill(state[editMode]);renderPresets()};
  sync();
  document.addEventListener('click',event=>{const modeButton=event.target.closest('[data-theme-mode]');if(modeButton){api.setMode(modeButton.dataset.themeMode);editMode=modeButton.dataset.themeMode;sync();announce(`${editMode==='dark'?'Dark':'Light'} mode applied`)}const editButton=event.target.closest('[data-edit-mode]');if(editButton){editMode=editButton.dataset.editMode;sync()}const presetButton=event.target.closest('[data-use-preset]');if(presetButton){editMode=presetButton.dataset.presetMode;api.usePreset(editMode,presetButton.dataset.usePreset);sync();announce(`${api.presets[editMode][presetButton.dataset.usePreset].name} preset applied`)}});
  form.addEventListener('input',()=>api.apply(values(),editMode));
  form.addEventListener('submit',event=>{event.preventDefault();api.save(values(),editMode,'custom');sync();announce(`${editMode==='dark'?'Dark':'Light'} custom colors saved`)});
  $('#reset-theme').addEventListener('click',()=>{api.reset(editMode);sync();announce(`${editMode==='dark'?'Dark':'Light'} colors reset`)});
}
function clientRow(client){const active=client.status==='active',profile=normalizeServiceProfile(client.serviceProfile||{preset:'quick'}),preset=SERVICE_PRESETS[profile.preset],serviceLabel=profile.serviceModes.length===2?'Quick + Table':preset.name;return `<article class="platform-client-row" data-client-id="${esc(client.id)}"><div class="platform-client"><span>${esc(client.businessName.charAt(0).toUpperCase())}.</span><div><strong>${esc(client.businessName)}</strong><small>${esc(serviceLabel)} · ${esc(profile.locationName)}</small></div></div><code>${esc(client.prefix)}.</code><span class="platform-status${active?'':' inactive'}">${active?'Active':'Paused'}</span><div class="platform-row-actions"><button class="button primary" type="button" data-open-client>Admin workspace</button><a class="button outline" href="/menu/?business=${encodeURIComponent(client.slug)}">Customer view</a><button class="button subtle" type="button" data-toggle-client>${active?'Pause':'Activate'}</button></div></article>`}
function adminRow(client){return `<article class="platform-account-row"><div><strong>${esc(client.admin.name)}</strong><small>${esc(client.admin.email)}</small></div><span>${esc(client.businessName)}</span><code>${esc(client.admin.username)}</code><span class="platform-status">${esc(client.admin.access||'First login pending')}</span></article>`}
function render(){const active=clients.filter(client=>client.status==='active').length,count=clients.length;$('#metric-client-count').textContent=count;$('#metric-active-count').textContent=active;$('#metric-admin-count').textContent=count;$('#nav-client-count').textContent=count;$('#client-count-label').textContent=`${count} ${count===1?'client':'clients'}`;$('#admin-count-label').textContent=`${count} ${count===1?'account':'accounts'}`;$('#client-list').innerHTML=clients.map(clientRow).join('');$('#recent-client-list').innerHTML=clients.slice(-3).reverse().map(clientRow).join('');$('#admin-list').innerHTML=clients.map(adminRow).join('')}
function showView(view){$$('[data-view-panel]').forEach(panel=>panel.hidden=panel.dataset.viewPanel!==view);$$('nav [data-admin-view]').forEach(button=>button.classList.toggle('nav-active',button.dataset.adminView===view));const labels={overview:'QRK Admin overview',clients:'Client portals',accounts:'Client Admins',appearance:'Global appearance'};$('#platform-page-title').textContent=labels[view];document.title=`QRK MENU — ${labels[view]}`;window.scrollTo(0,0)}
const GATES={quick:[['consumption','Consumption','dine-in / takeaway'],['fulfillment','Fulfillment','table / pickup'],['quick_payment','Payment','counter'],['locator','Order locator','table number']],table:[['table_entry','Table entry','permanent QR'],['party_size','Party size','required'],['bundle','Bundle selection','none'],['entry_payment','Entry payment','none'],['entitlement','Entitlements & refills','none'],['time_limit','Time limit','none'],['quantity_limit','Quantity limit','none'],['payment_timing','Payment timing','at bill'],['joining','Joining','host approval'],['host_permissions','Host permissions','approve guest orders'],['bill_closure','Bill & closure','lock after bill'],['inactivity','Inactivity','120 min + grace']]};
let serviceBuilder={modes:new Set(['table']),preset:'traditional',gates:{quick:[],table:[]},settings:presetSettings('traditional')};
const csv=value=>String(value||'').split(',').map(item=>item.trim()).filter(Boolean);
const gateMeta=(mode,id)=>GATES[mode].find(item=>item[0]===id);
function gateSummary(id,s){if(id==='consumption')return(s.consumptionModes||[]).join(' / ');if(id==='fulfillment')return(s.fulfillmentModes||[]).join(' / ');if(id==='quick_payment')return(s.paymentModes||[]).join(' / ');if(id==='locator')return s.locatorMode||'table';if(id==='table_entry')return{qr:'permanent QR',choose:'customer chooses',staff:'staff assigns'}[s.tableIdentification]||'permanent QR';if(id==='bundle')return s.bundleSelection||'required';if(id==='entry_payment')return(s.entryPayment||'deposit').replace('_',' ');if(id==='entitlement')return`${s.entitlementMode||'bundle'} · ${s.refillPolicy||'none'} refills`;if(id==='time_limit')return`${s.timeLimitMinutes||90} minutes`;if(id==='quantity_limit')return`${s.quantityLimit||1} included`;if(id==='payment_timing')return(s.paymentTiming||'end').replace('_',' ');if(id==='joining')return(s.joinPolicy||'host').replace('_',' ');if(id==='host_permissions')return(s.guestOrderPolicy||'host_approval').replaceAll('_',' ');if(id==='bill_closure')return s.billLocksOrdering?'locks after bill':'ordering stays open';if(id==='inactivity')return`${s.inactivityMinutes||120} min + ${s.inactivityGraceMinutes||15} grace`;return''}
function orderFor(settings){if(settings.serviceMode==='quick')return{quick:['consumption','fulfillment','quick_payment',...(settings.locatorMode&&settings.locatorMode!=='none'?['locator']:[])],table:[]};return{quick:[],table:['table_entry',...(settings.guestCountRequired?['party_size']:[]),...(settings.bundleSelection!=='none'?['bundle']:[]),...(settings.entryPayment!=='none'?['entry_payment']:[]),...(settings.entitlementMode!=='none'?['entitlement']:[]),...(settings.timeLimitMinutes?['time_limit']:[]),...(settings.quantityLimit?['quantity_limit']:[]),'payment_timing',...(settings.additionalDevices?['joining','host_permissions']:[]),'bill_closure','inactivity']}}
function field(label,control){return`<label>${label}${control}</label>`}
function gateControls(id,s){const select=(key,options)=>`<select data-gate-field="${key}">${options.map(([value,label])=>`<option value="${value}"${s[key]===value?' selected':''}>${label}</option>`).join('')}</select>`,number=(key,value,min=0)=>`<input data-gate-field="${key}" type="number" min="${min}" value="${Number(value)||0}">`;if(id==='consumption')return field('Choices','<input data-gate-field="consumptionModes" value="'+esc((s.consumptionModes||['dine_in','takeaway']).join(', '))+'">');if(id==='fulfillment')return field('Choices','<input data-gate-field="fulfillmentModes" value="'+esc((s.fulfillmentModes||['table','pickup']).join(', '))+'">');if(id==='quick_payment')return field('Choices','<input data-gate-field="paymentModes" value="'+esc((s.paymentModes||['counter']).join(', '))+'">');if(id==='locator')return field('Locator',select('locatorMode',[['table','Table number'],['name','Customer name'],['pager','Pager number']]));if(id==='table_entry')return field('Entry',select('tableIdentification',[['qr','Permanent table QR'],['choose','Choose a table'],['staff','Staff assigns']]));if(id==='bundle')return field('Selection',select('bundleSelection',[['required','Required'],['optional','Optional']]));if(id==='entry_payment')return field('Rule',select('entryPayment',[['deposit','Deposit'],['minimum_spend','Minimum spend'],['full','Full prepayment']]))+field('Amount PHP',number('entryAmount',(s.entryPayment==='minimum_spend'?s.minimumSpendMinor:s.entryAmountMinor)/100));if(id==='entitlement')return field('Rule',select('entitlementMode',[['bundle','Bundle inclusions'],['quantity','Limited quantity']]))+field('Refills',select('refillPolicy',[['included','Included'],['limited','Limited'],['none','None']]));if(id==='time_limit')return field('Minutes',number('timeLimitMinutes',s.timeLimitMinutes,1));if(id==='quantity_limit')return field('Included quantity',number('quantityLimit',s.quantityLimit,1));if(id==='payment_timing')return field('Timing',select('paymentTiming',[['end','At bill'],['upfront','Upfront'],['split','Package first, extras later'],['on_exit','On exit']]));if(id==='joining')return field('Approval',select('joinPolicy',[['host','Host approves'],['staff','Staff approves'],['code','Join code'],['open','Open joining']]));if(id==='host_permissions')return field('Guest orders',select('guestOrderPolicy',[['host_approval','Host approves'],['direct','Direct'],['shared_cart','Shared cart'],['view_only','View only']]));if(id==='bill_closure')return field('Closure',select('closureRule',[['staff_after_payment','Staff closes after payment'],['host_request','Host requests closure']]))+`<label class="gate-check"><input data-gate-field="billLocksOrdering" type="checkbox"${s.billLocksOrdering?' checked':''}> Lock ordering after bill request</label>`;if(id==='inactivity')return field('Warning minutes',number('inactivityMinutes',s.inactivityMinutes||120,15))+field('Grace minutes',number('inactivityGraceMinutes',s.inactivityGraceMinutes||15,1));return'<small>No additional settings.</small>'}
function renderGateBoards(){const form=$('#client-form');form.elements.serviceModeQuick.checked=serviceBuilder.modes.has('quick');form.elements.serviceModeTable.checked=serviceBuilder.modes.has('table');$('#gate-boards').innerHTML=['quick','table'].filter(mode=>serviceBuilder.modes.has(mode)).map(mode=>{const active=serviceBuilder.gates[mode],available=GATES[mode].filter(([id])=>!active.includes(id));return`<section class="gate-board" data-gate-mode="${mode}"><header><strong>${mode==='quick'?'Quick':'Table'} journey</strong><span>${active.length} gates</span></header><div class="gate-list" data-gate-list="${mode}">${active.map((id,index)=>{const meta=gateMeta(mode,id);return`<article class="gate-item" draggable="true" data-gate-id="${id}"><button class="gate-grip" type="button" data-move-gate="${id}" aria-label="Move ${esc(meta[1])} down">↕</button><div><strong><span>${index+1}</span>${esc(meta[1])}</strong><small>${esc(gateSummary(id,serviceBuilder.settings))}</small><details><summary>Configure</summary><div class="gate-fields">${gateControls(id,serviceBuilder.settings)}</div></details></div><button class="gate-remove" type="button" data-remove-gate="${id}" aria-label="Remove ${esc(meta[1])}">×</button></article>`}).join('')||'<p class="gate-empty">No gates yet. Add one below.</p>'}</div><div class="gate-add"><select aria-label="Add ${mode} gate">${available.map(([id,label])=>`<option value="${id}">${esc(label)}</option>`).join('')}</select><button class="button outline" type="button" data-add-gate="${mode}"${available.length?'':' disabled'}>Add gate</button></div></section>`}).join('');updateFormPreviews()}
function applyPreset(id){const settings=presetSettings(id),mode=settings.serviceMode,next=orderFor(settings);if(serviceBuilder.modes.size>1){serviceBuilder.gates[mode]=next[mode];serviceBuilder.settings={...serviceBuilder.settings,...settings,serviceMode:'table',serviceModes:[...serviceBuilder.modes]};serviceBuilder.preset='custom'}else serviceBuilder={modes:new Set([mode]),preset:id,gates:next,settings};$('#preset-choice').value=id;renderGateBoards()}
function readServiceProfile(){const modes=[...serviceBuilder.modes],settings={...serviceBuilder.settings,serviceMode:modes.includes('table')?'table':'quick',serviceModes:modes,gateOrder:{quick:[...serviceBuilder.gates.quick],table:[...serviceBuilder.gates.table]}};if(modes.includes('quick')){for(const [gate,key,fallback] of [['consumption','consumptionModes',['dine_in']],['fulfillment','fulfillmentModes',['pickup']],['quick_payment','paymentModes',['counter']]])settings[key]=serviceBuilder.gates.quick.includes(gate)?settings[key]||fallback:fallback;settings.locatorMode=serviceBuilder.gates.quick.includes('locator')?settings.locatorMode||'table':'none'}if(modes.includes('table')){settings.guestCountRequired=serviceBuilder.gates.table.includes('party_size');settings.bundleSelection=serviceBuilder.gates.table.includes('bundle')?settings.bundleSelection||'required':'none';settings.packageMode=settings.bundleSelection==='required'?'required':'none';settings.entryPayment=serviceBuilder.gates.table.includes('entry_payment')?settings.entryPayment||'deposit':'none';settings.entitlementMode=serviceBuilder.gates.table.includes('entitlement')?settings.entitlementMode||'bundle':'none';settings.timeLimitMinutes=serviceBuilder.gates.table.includes('time_limit')?Number(settings.timeLimitMinutes)||90:0;settings.quantityLimit=serviceBuilder.gates.table.includes('quantity_limit')?Number(settings.quantityLimit)||1:0;settings.additionalDevices=serviceBuilder.gates.table.includes('joining');settings.joinPolicy=settings.additionalDevices?settings.joinPolicy||'host':'disabled';settings.billLocksOrdering=serviceBuilder.gates.table.includes('bill_closure')&&settings.billLocksOrdering!==false}return normalizeServiceProfile({preset:serviceBuilder.preset,serviceModes:modes,locationName:$('#client-form').elements.locationName.value.trim()||'Main location',settings})}
function updateFormPreviews(){const form=$('#client-form'),name=form.elements.businessName.value,slug=segment(form.elements.slug.value||name),prefix=usernameSegment(form.elements.prefix.value||segment(name).split('-')[0]),suffix=usernameSegment(form.elements.adminUsername.value)||'admin',profile=readServiceProfile(),journeys=profile.serviceModes.map(mode=>`${mode==='quick'?'Quick':'Table'}: ${profile.settings.gateOrder[mode].map(id=>gateMeta(mode,id)?.[1]).join(' → ')||'no gates'}`);$('#slug-preview').textContent=slug||'business-name';$('#admin-prefix-preview').textContent=`${prefix||'client'}.`;$('#admin-username-preview').textContent=`Login username: ${prefix||'client'}.${suffix}`;$('#journey-preview').textContent=`${profile.locationName} · ${journeys.join(' · ')}`}
function openClientDialog(){const form=$('#client-form');form.reset();$('#client-form-error').textContent='';$('#preset-choice').innerHTML=Object.values(SERVICE_PRESETS).filter(preset=>preset.id!=='custom').map(preset=>`<option value="${preset.id}">${esc(preset.name)}</option>`).join('');applyPreset('traditional');$('#client-dialog').showModal();form.elements.businessName.focus()}
$('#platform-continue').addEventListener('click',()=>{$('#platform-login').hidden=true;$('#platform-shell').hidden=false;showView('overview');render()});
$('#platform-logout').addEventListener('click',()=>{$('#platform-shell').hidden=true;$('#platform-login').hidden=false;document.title='QRK MENU — QRK Admin';$('#platform-continue').focus()});
document.addEventListener('click',async event=>{const view=event.target.closest('[data-admin-view]');if(view)showView(view.dataset.adminView);if(event.target.closest('[data-add-client]'))openClientDialog();if(event.target.closest('.close-dialog'))event.target.closest('dialog').close();const openClient=event.target.closest('[data-open-client]');if(openClient){const id=openClient.closest('[data-client-id]').dataset.clientId,client=clients.find(item=>item.id===id);try{await authService.signInDevelopment({displayName:client.admin.name,username:client.admin.username,businessId:`preview:${client.slug}`,businessName:client.businessName,businessSlug:client.slug,serviceMode:client.serviceProfile.settings.serviceMode,role:'admin',permissions:{viewOrders:true,acceptOrders:true,prepareOrders:true,markReady:true,completeOrders:true,cancelOrders:true,changeAvailability:true,editMenu:true,viewOrderHistory:true,viewSales:true,manageStaff:true}});location.href='/'}catch(reason){announce(reason.message)}}const toggle=event.target.closest('[data-toggle-client]');if(toggle){const id=toggle.closest('[data-client-id]').dataset.clientId,client=clients.find(item=>item.id===id);client.status=client.status==='active'?'paused':'active';saveClients();render();announce(`${client.businessName} ${client.status==='active'?'activated':'paused'} in this preview`)}});
const clientForm=$('#client-form');
clientForm.elements.businessName.addEventListener('input',event=>{if(!clientForm.elements.slug.dataset.edited)clientForm.elements.slug.value=segment(event.target.value);if(!clientForm.elements.prefix.dataset.edited)clientForm.elements.prefix.value=usernameSegment(segment(event.target.value).split('-')[0]);updateFormPreviews()});
clientForm.elements.slug.addEventListener('input',event=>{event.target.dataset.edited='true';event.target.value=segment(event.target.value);updateFormPreviews()});clientForm.elements.prefix.addEventListener('input',event=>{event.target.dataset.edited='true';event.target.value=usernameSegment(event.target.value);updateFormPreviews()});clientForm.elements.adminUsername.addEventListener('input',event=>{event.target.value=usernameSegment(event.target.value);updateFormPreviews()});clientForm.addEventListener('reset',()=>{delete clientForm.elements.slug.dataset.edited;delete clientForm.elements.prefix.dataset.edited;requestAnimationFrame(updateFormPreviews)});
