clientForm.addEventListener('change',event=>{if(['serviceModeQuick','serviceModeTable'].includes(event.target.name)){const mode=event.target.name==='serviceModeQuick'?'quick':'table';event.target.checked?serviceBuilder.modes.add(mode):serviceBuilder.modes.delete(mode);if(!serviceBuilder.modes.size){serviceBuilder.modes.add(mode);event.target.checked=true}if(!serviceBuilder.gates[mode].length&&event.target.checked){const seed=presetSettings(mode==='quick'?'quick':'traditional');serviceBuilder.gates[mode]=orderFor(seed)[mode];serviceBuilder.settings={...seed,...serviceBuilder.settings,serviceMode:serviceBuilder.modes.has('table')?'table':'quick'}}renderGateBoards();return}const field=event.target.dataset.gateField;if(field){serviceBuilder.settings[field]=event.target.type==='checkbox'?event.target.checked:event.target.type==='number'?Number(event.target.value):field.endsWith('Modes')?csv(event.target.value):event.target.value;if(field==='entryAmount'){serviceBuilder.settings.entryAmountMinor=Number(event.target.value)*100;serviceBuilder.settings.minimumSpendMinor=Number(event.target.value)*100}updateFormPreviews();return}updateFormPreviews()});clientForm.addEventListener('input',event=>{const field=event.target.dataset.gateField;if(field){serviceBuilder.settings[field]=event.target.type==='number'?Number(event.target.value):field.endsWith('Modes')?csv(event.target.value):event.target.value;if(field==='entryAmount'){serviceBuilder.settings.entryAmountMinor=Number(event.target.value)*100;serviceBuilder.settings.minimumSpendMinor=Number(event.target.value)*100}}if(!['businessName','slug','prefix','adminUsername'].includes(event.target.name))updateFormPreviews()});
$('#gate-boards').addEventListener('click',event=>{const move=event.target.closest('[data-move-gate]');if(move){const mode=move.closest('[data-gate-mode]').dataset.gateMode,order=serviceBuilder.gates[mode],at=order.indexOf(move.dataset.moveGate),next=(at+1)%order.length;order.splice(next,0,order.splice(at,1)[0]);renderGateBoards();return}const remove=event.target.closest('[data-remove-gate]');if(remove){const board=remove.closest('[data-gate-mode]'),mode=board.dataset.gateMode;serviceBuilder.gates[mode]=serviceBuilder.gates[mode].filter(id=>id!==remove.dataset.removeGate);renderGateBoards();return}const add=event.target.closest('[data-add-gate]');if(add){const mode=add.dataset.addGate,select=add.previousElementSibling,id=select.value;if(id)serviceBuilder.gates[mode].push(id);renderGateBoards()}});
let draggedGate=null;$('#gate-boards').addEventListener('dragstart',event=>{const item=event.target.closest('[data-gate-id]');if(!item)return;draggedGate={mode:item.closest('[data-gate-mode]').dataset.gateMode,id:item.dataset.gateId};item.classList.add('dragging')});$('#gate-boards').addEventListener('dragend',event=>{event.target.closest('[data-gate-id]')?.classList.remove('dragging');draggedGate=null});$('#gate-boards').addEventListener('dragover',event=>{const item=event.target.closest('[data-gate-id]');if(item&&draggedGate?.mode===item.closest('[data-gate-mode]').dataset.gateMode)event.preventDefault()});$('#gate-boards').addEventListener('drop',event=>{const item=event.target.closest('[data-gate-id]');if(!item||!draggedGate)return;event.preventDefault();const order=serviceBuilder.gates[draggedGate.mode],from=order.indexOf(draggedGate.id),to=order.indexOf(item.dataset.gateId);if(from>=0&&to>=0){order.splice(to,0,order.splice(from,1)[0]);renderGateBoards()}});
clientForm.addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget,businessName=form.elements.businessName.value.trim(),slug=segment(form.elements.slug.value),prefix=usernameSegment(form.elements.prefix.value),suffix=usernameSegment(form.elements.adminUsername.value),username=`${prefix}.${suffix}`,error=$('#client-form-error');error.textContent='';if(clients.some(client=>client.slug===slug)){error.textContent='That portal slug is already in use.';form.elements.slug.focus();return}if(clients.some(client=>client.prefix===prefix)){error.textContent='That username prefix is already in use.';form.elements.prefix.focus();return}let credentials;try{credentials=authService.createPreviewUser({displayName:form.elements.adminName.value.trim(),username,email:form.elements.adminEmail.value.trim(),role:'admin',permissions:{viewOrders:true,acceptOrders:true,prepareOrders:true,markReady:true,completeOrders:true,cancelOrders:true,changeAvailability:true,editMenu:true,viewOrderHistory:true,viewSales:true,manageStaff:true},businessId:`preview:${slug}`,businessName,businessSlug:slug,active:true})}catch(reason){error.textContent=reason.message;return}clients.push({id:`client-${Date.now()}`,businessName,slug,prefix,status:'active',createdAt:new Date().toISOString(),serviceProfile:readServiceProfile(),admin:{name:form.elements.adminName.value.trim(),email:form.elements.adminEmail.value.trim(),username,access:'First login pending'}});saveClients();render();$('#client-dialog').close();$('#created-admin-username').textContent=credentials.username;$('#created-admin-password').textContent=credentials.temporaryPassword;$('#credentials-dialog').showModal();announce(`${businessName} client portal created`)});
$('#copy-client-login').addEventListener('click',async()=>{const value=`QRK MENU Client Admin login\nUsername: ${$('#created-admin-username').textContent}\nTemporary password: ${$('#created-admin-password').textContent}\nPortal: ${location.origin}/`;try{await navigator.clipboard.writeText(value);announce('Client Admin login copied')}catch{announce('Copy the login details shown')}});initializeThemeEditor();render();
